const uint16_t *get_iw2_nlq_glyph(uint8_t ch)
{
    if (ch < 4 || ch >= 128) return nullptr;
    return font_iw2_nlq[ch - 4];
}

uint8_t get_iw2_nlq_width(uint8_t ch)
{
    if (ch < 4 || ch >= 128) return 0;
    return iw2_nlq_width[ch - 4];
}

